// JSON-schema guided decoding: schema compilation + byte-level run state.
//
// The automaton is a small pushdown machine over the generated bytes.  Each
// stack frame is one JSON value being parsed (object, array, string, number or
// an exact literal); the schema attached to that frame decides which value
// types, property names, enum spellings and lengths are allowed next.  A run
// state is a *set* of such stacks because anyOf/oneOf (and nullable type
// arrays) may admit several parses of the same prefix; branches that a byte
// contradicts are dropped, and the set collapses back to one as soon as the
// first discriminating byte arrives.
//
// Everything here is byte-based on purpose: the sampler sees vocabulary pieces,
// not decoded Unicode, and a token may split a UTF-8 sequence, an escape or a
// number.  The only place that decodes is the object-key matcher, which needs
// the actual property name (and handles \uXXXX there).
#include "guided.h"

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
