namespace si {

namespace {

using json = nlohmann::json;

// ---------------------------------------------------------------------------
// schema
// ---------------------------------------------------------------------------

enum type_bit : uint32_t {
    T_NULL = 1u << 0,
    T_BOOL = 1u << 1,
    T_OBJ = 1u << 2,
    T_ARR = 1u << 3,
    T_STR = 1u << 4,
    T_NUM = 1u << 5,
    T_INT = 1u << 6,
};
constexpr uint32_t kAllTypes = T_NULL | T_BOOL | T_OBJ | T_ARR | T_STR | T_NUM;

struct schema_node;

struct prop_def {
    std::string name;
    std::shared_ptr<schema_node> schema;
};

struct schema_node {
    uint32_t types = 0; // 0 = unconstrained
    bool never = false;
    // $ref stores a raw pointer for the hot path.  All compiled nodes are kept
    // alive by guided_constraint::arena (the builder's memo is temporary);
    // deliberately not a shared_ptr here, so a recursive schema cannot form a
    // reference cycle.
    const schema_node * ref = nullptr;

    std::vector<std::shared_ptr<schema_node>> alts; // anyOf / oneOf

    // object
    std::vector<prop_def> props;
    std::vector<uint8_t> required; // parallel to props
    int additional = 1;            // 0 = false, 1 = true, 2 = schema
    std::shared_ptr<schema_node> additional_schema;
    int min_props = -1;
    int max_props = -1;

    // array
    std::shared_ptr<schema_node> items;
    int min_items = -1;
    int max_items = -1;

    // string
    int min_len = -1;
    int max_len = -1;
    bool has_pattern = false;
    std::string pattern;

    // enum / const: exact JSON spellings of the allowed values (quotes included
    // for strings).  This subsumes string enum and const handling and makes a
    // numeric/boolean enum work without a special number matcher.
    std::vector<std::string> enum_forms;

    // number
    bool has_min = false, min_excl = false;
    double min_v = 0;
    bool has_max = false, max_excl = false;
    double max_v = 0;
    bool has_multiple = false;
    double multiple = 0;
};

std::string json_escape(const std::string & s) {
    std::string out = "\"";
    for (unsigned char c : s) {
        switch (c) {
        case '"': out += "\\\""; break;
        case '\\': out += "\\\\"; break;
        case '\b': out += "\\b"; break;
        case '\f': out += "\\f"; break;
        case '\n': out += "\\n"; break;
        case '\r': out += "\\r"; break;
        case '\t': out += "\\t"; break;
        default:
            if (c < 0x20) {
                char b[8];
                snprintf(b, sizeof(b), "\\u%04x", c);
                out += b;
            } else {
                out += (char)c;
            }
        }
    }
    out += '"';
    return out;
}

std::string canonical_form(const json & v) {
    if (v.is_string()) {
        return json_escape(v.get<std::string>());
    }
    if (v.is_boolean()) {
        return v.get<bool>() ? "true" : "false";
    }
    if (v.is_null()) {
        return "null";
    }
    if (v.is_number()) {
        // nlohmann's dump is the shortest round-tripping spelling for a number
        return v.dump();
    }
    return v.dump();
}

uint32_t type_from_name(const std::string & s) {
    if (s == "null") {
        return T_NULL;
    }
    if (s == "boolean") {
        return T_BOOL;
    }
    if (s == "object") {
        return T_OBJ;
    }
    if (s == "array") {
        return T_ARR;
    }
    if (s == "string") {
        return T_STR;
    }
    if (s == "number") {
        return T_NUM;
    }
    if (s == "integer") {
        return T_INT;
    }
    return 0;
}

struct schema_builder {
    const json * root = nullptr;
    std::unordered_map<std::string, const json *> defs;
    std::unordered_map<const json *, std::shared_ptr<schema_node>> memo;

    std::shared_ptr<schema_node> any_node() {
        auto n = std::make_shared<schema_node>();
        n->types = kAllTypes;
        return n;
    }
    std::shared_ptr<schema_node> never_node() {
        auto n = std::make_shared<schema_node>();
        n->never = true;
        return n;
    }

    const json * find_ref(const std::string & ref, int depth) {
        if (depth > 32) {
            return nullptr;
        }
        if (ref == "#") {
            return root;
        }
        static const char * prefixes[] = {"#/$defs/", "#/definitions/"};
        for (const char * p : prefixes) {
            const size_t pl = strlen(p);
            if (ref.compare(0, pl, p) == 0) {
                auto it = defs.find(ref.substr(pl));
                return it == defs.end() ? nullptr : it->second;
            }
        }
        return nullptr;
    }

    std::shared_ptr<schema_node> compile(const json & j, int depth) {
        if (depth > 64) {
            return any_node();
        }
        auto it = memo.find(&j);
        if (it != memo.end()) {
            return it->second;
        }
        if (j.is_boolean()) {
            return j.get<bool>() ? any_node() : never_node();
        }
        if (!j.is_object()) {
            return any_node();
        }
        auto n = std::make_shared<schema_node>();
        memo[&j] = n;
        fill(n, j, depth);
        return n;
    }

    void fill(const std::shared_ptr<schema_node> & n, const json & j, int depth) {
        if (j.contains("$ref") && j["$ref"].is_string()) {
            const json * tgt = find_ref(j["$ref"].get<std::string>(), depth + 1);
            if (tgt == nullptr) {
                return; // unresolvable (external / malformed) ref: permissive
            }
            n->ref = compile(*tgt, depth + 1).get();
            // 2020-12 allows sibling keywords next to $ref; apply them as an
            // allOf rest.  The common case is $ref alone, which leaves `ref`
            // as the only thing to follow.
            if (j.size() > 1) {
                json rest = j;
                rest.erase("$ref");
                auto other = compile(rest, depth + 1);
                auto merged = merge_all(n, other);
                *n = *merged;
                return;
            }
            return;
        }

        if (j.contains("anyOf") && j["anyOf"].is_array()) {
            for (const auto & a : j["anyOf"]) {
                n->alts.push_back(compile(a, depth + 1));
            }
            return;
        }
        if (j.contains("oneOf") && j["oneOf"].is_array()) {
            for (const auto & a : j["oneOf"]) {
                n->alts.push_back(compile(a, depth + 1));
            }
            return;
        }
        if (j.contains("allOf") && j["allOf"].is_array()) {
            std::shared_ptr<schema_node> acc;
            for (const auto & a : j["allOf"]) {
                auto part = compile(a, depth + 1);
                acc = acc ? merge_all(acc, part) : part;
            }
            if (acc) {
                if (j.size() == 1) {
                    *n = *acc;
                    return;
                }
                json rest = j;
                rest.erase("allOf");
                *n = *merge_all(acc, compile(rest, depth + 1));
                return;
            }
        }

        if (j.contains("const")) {
            n->enum_forms.push_back(canonical_form(j["const"]));
            return;
        }
        if (j.contains("enum") && j["enum"].is_array()) {
            for (const auto & e : j["enum"]) {
                n->enum_forms.push_back(canonical_form(e));
            }
            if (n->enum_forms.empty()) {
                n->never = true;
            }
            return;
        }

        if (j.contains("type")) {
            const json & t = j["type"];
            if (t.is_string()) {
                n->types = type_from_name(t.get<std::string>());
            } else if (t.is_array()) {
                for (const auto & e : t) {
                    if (e.is_string()) {
                        n->types |= type_from_name(e.get<std::string>());
                    }
                }
            }
            if (n->types == 0) {
                n->never = true;
                return;
            }
        }

        if (j.contains("properties") && j["properties"].is_object()) {
            for (auto it = j["properties"].begin(); it != j["properties"].end(); ++it) {
                prop_def p;
                p.name = it.key();
                p.schema = compile(it.value(), depth + 1);
                n->props.push_back(std::move(p));
            }
        }
        n->required.assign(n->props.size(), 0);
        if (j.contains("required") && j["required"].is_array()) {
            for (const auto & r : j["required"]) {
                if (!r.is_string()) {
                    continue;
                }
                const std::string name = r.get<std::string>();
                for (size_t i = 0; i < n->props.size(); i++) {
                    if (n->props[i].name == name) {
                        n->required[i] = 1;
                        break;
                    }
                }
            }
        }
        if (j.contains("additionalProperties")) {
            const json & ap = j["additionalProperties"];
            if (ap.is_boolean()) {
                n->additional = ap.get<bool>() ? 1 : 0;
            } else if (ap.is_object()) {
                n->additional = 2;
                n->additional_schema = compile(ap, depth + 1);
            }
        }
        if (j.contains("minProperties") && j["minProperties"].is_number_integer()) {
            n->min_props = j["minProperties"].get<int>();
        }
        if (j.contains("maxProperties") && j["maxProperties"].is_number_integer()) {
            n->max_props = j["maxProperties"].get<int>();
        }

        if (j.contains("items")) {
            if (j["items"].is_object() || j["items"].is_boolean()) {
                n->items = compile(j["items"], depth + 1);
            }
        }
        if (j.contains("minItems") && j["minItems"].is_number_integer()) {
            n->min_items = j["minItems"].get<int>();
        }
        if (j.contains("maxItems") && j["maxItems"].is_number_integer()) {
            n->max_items = j["maxItems"].get<int>();
        }

        if (j.contains("minLength") && j["minLength"].is_number_integer()) {
            n->min_len = j["minLength"].get<int>();
        }
        if (j.contains("maxLength") && j["maxLength"].is_number_integer()) {
            n->max_len = j["maxLength"].get<int>();
        }
        if (j.contains("pattern") && j["pattern"].is_string()) {
            n->has_pattern = true;
            n->pattern = j["pattern"].get<std::string>();
        }

        auto set_num = [&](const char * k, bool & has, double & v) {
            if (j.contains(k) && j[k].is_number()) {
                has = true;
                v = j[k].get<double>();
            }
        };
        set_num("minimum", n->has_min, n->min_v);
        set_num("maximum", n->has_max, n->max_v);
        if (j.contains("exclusiveMinimum")) {
            const json & x = j["exclusiveMinimum"];
            if (x.is_number()) {
                n->has_min = true;
                n->min_excl = true;
                n->min_v = x.get<double>();
            } else if (x.is_boolean() && x.get<bool>()) {
                n->min_excl = true;
            }
        }
        if (j.contains("exclusiveMaximum")) {
            const json & x = j["exclusiveMaximum"];
            if (x.is_number()) {
                n->has_max = true;
                n->max_excl = true;
                n->max_v = x.get<double>();
            } else if (x.is_boolean() && x.get<bool>()) {
                n->max_excl = true;
            }
        }
        if (j.contains("multipleOf") && j["multipleOf"].is_number()) {
            const double m = j["multipleOf"].get<double>();
            if (m > 0) {
                n->has_multiple = true;
                n->multiple = m;
            }
        }
    }

    // allOf: intersect two schemas.  This is best-effort (it is exact for the
    // shapes OpenAI-style strict schemas use: required/keyword unions, tighter
    // bounds, enum intersection, property-wise merge), and it is applied while
    // compiling rather than at parse time so a run state never has to carry a
    // conjunction.
    std::shared_ptr<schema_node> merge_all(const std::shared_ptr<schema_node> & a,
                                           const std::shared_ptr<schema_node> & b) {
        if (!a) {
            return b;
        }
        if (!b) {
            return a;
        }
        if (a->never || b->never) {
            return never_node();
        }
        const schema_node * ar = follow(a.get());
        const schema_node * br = follow(b.get());
        // Alternatives: pairwise-merge the variants (bounded; a schema with
        // hundreds of anyOf branches in an allOf is not a real workload).
        if (!ar->alts.empty() || !br->alts.empty()) {
            std::vector<const schema_node *> av, bv;
            variants(ar, av);
            variants(br, bv);
            auto out = std::make_shared<schema_node>();
            for (const schema_node * x : av) {
                for (const schema_node * y : bv) {
                    if (out->alts.size() >= 128) {
                        break;
                    }
                    auto xc = clone_node(x);
                    auto yc = clone_node(y);
                    out->alts.push_back(merge_all(xc, yc));
                }
            }
            if (out->alts.empty()) {
                return never_node();
            }
            return out;
        }

        auto n = std::make_shared<schema_node>();
        n->types = ar->types & br->types;
        if (ar->types == 0) {
            n->types = br->types;
        } else if (br->types == 0) {
            n->types = ar->types;
        }
        if (ar->types != 0 && br->types != 0 && n->types == 0) {
            return never_node();
        }

        // enum: intersection
        if (!ar->enum_forms.empty() && !br->enum_forms.empty()) {
            for (const auto & x : ar->enum_forms) {
                if (std::find(br->enum_forms.begin(), br->enum_forms.end(), x) != br->enum_forms.end()) {
                    n->enum_forms.push_back(x);
                }
            }
            if (n->enum_forms.empty()) {
                return never_node();
            }
        } else if (!ar->enum_forms.empty()) {
            n->enum_forms = ar->enum_forms;
        } else {
            n->enum_forms = br->enum_forms;
        }

        n->props = ar->props;
        n->required = ar->required;
        n->required.resize(n->props.size(), 0);
        for (const auto & pb : br->props) {
            bool found = false;
            for (size_t i = 0; i < n->props.size(); i++) {
                if (n->props[i].name == pb.name) {
                    n->props[i].schema = merge_all(n->props[i].schema, pb.schema);
                    found = true;
                    break;
                }
            }
            if (!found) {
                n->props.push_back(pb);
                n->required.push_back(0);
            }
        }
        for (size_t i = 0; i < br->props.size(); i++) {
            if (!br->required.empty() && br->required[i]) {
                for (size_t j = 0; j < n->props.size(); j++) {
                    if (n->props[j].name == br->props[i].name) {
                        n->required[j] = 1;
                    }
                }
            }
        }

        // additionalProperties: stricter wins; two schemas merge.
        if (ar->additional == 0 || br->additional == 0) {
            n->additional = 0;
        } else if (ar->additional == 2 && br->additional == 2) {
            n->additional = 2;
            n->additional_schema = merge_all(ar->additional_schema, br->additional_schema);
        } else if (ar->additional == 2) {
            n->additional = 2;
            n->additional_schema = ar->additional_schema;
        } else if (br->additional == 2) {
            n->additional = 2;
            n->additional_schema = br->additional_schema;
        } else {
            n->additional = 1;
        }

        n->items = (ar->items && br->items) ? merge_all(ar->items, br->items) : (ar->items ? ar->items : br->items);
        n->min_items = max_bound(ar->min_items, br->min_items);
        n->max_items = min_bound(ar->max_items, br->max_items);
        n->min_props = max_bound(ar->min_props, br->min_props);
        n->max_props = min_bound(ar->max_props, br->max_props);
        n->min_len = max_bound(ar->min_len, br->min_len);
        n->max_len = min_bound(ar->max_len, br->max_len);
        n->has_min = ar->has_min || br->has_min;
        if (ar->has_min && (!br->has_min || ar->min_v > br->min_v)) {
            n->min_v = ar->min_v;
            n->min_excl = ar->min_excl;
        } else {
            n->min_v = br->min_v;
            n->min_excl = br->min_excl;
        }
        n->has_max = ar->has_max || br->has_max;
        if (ar->has_max && (!br->has_max || ar->max_v < br->max_v)) {
            n->max_v = ar->max_v;
            n->max_excl = ar->max_excl;
        } else {
            n->max_v = br->max_v;
            n->max_excl = br->max_excl;
        }
        if (ar->has_multiple && br->has_multiple) {
            // lcm is exact for integer multiples; keep the larger one otherwise
            n->has_multiple = true;
            n->multiple = std::max(ar->multiple, br->multiple);
        } else if (ar->has_multiple) {
            n->has_multiple = true;
            n->multiple = ar->multiple;
        } else if (br->has_multiple) {
            n->has_multiple = true;
            n->multiple = br->multiple;
        }
        if (ar->has_pattern && br->has_pattern && ar->pattern == br->pattern) {
            n->has_pattern = true;
            n->pattern = ar->pattern;
        } else if (ar->has_pattern && !br->has_pattern) {
            n->has_pattern = true;
            n->pattern = ar->pattern;
        } else if (br->has_pattern && !ar->has_pattern) {
            n->has_pattern = true;
            n->pattern = br->pattern;
        }
        if (n->min_items >= 0 && n->max_items >= 0 && n->min_items > n->max_items) {
            return never_node();
        }
        if (n->min_props >= 0 && n->max_props >= 0 && n->min_props > n->max_props) {
            return never_node();
        }
        if (n->min_len >= 0 && n->max_len >= 0 && n->min_len > n->max_len) {
            return never_node();
        }
        return n;
    }

    static int max_bound(int a, int b) {
        return a < 0 ? b : (b < 0 ? a : std::max(a, b));
    }
    static int min_bound(int a, int b) {
        return a < 0 ? b : (b < 0 ? a : std::min(a, b));
    }

    static const schema_node * follow(const schema_node * n) {
        for (int i = 0; i < 64 && n && n->ref; i++) {
            if (n->ref == n) {
                return n;
            }
            n = n->ref;
        }
        return n;
    }

    static std::shared_ptr<schema_node> clone_node(const schema_node * n) {
        auto c = std::make_shared<schema_node>();
        *c = *n;
        return c;
    }

    static void variants(const schema_node * n, std::vector<const schema_node *> & out) {
        n = follow(n);
        if (!n) {
            return;
        }
        if (n->alts.empty()) {
            out.push_back(n);
            return;
        }
        for (const auto & a : n->alts) {
            variants(a.get(), out);
        }
    }
};

// ---------------------------------------------------------------------------
// parser run state
// ---------------------------------------------------------------------------

enum frame_kind : uint8_t { K_ROOT, K_OBJ, K_ARR, K_STR, K_NUM, K_LIT };

enum frame_phase : uint8_t {
    P_VALUE,
    P_VALUE_OR_END,
    P_VALUE_AFTER_COMMA,
    P_KEY_OR_END,
    P_KEY_AFTER_COMMA,
    P_KEY,
    P_COLON,
    P_COMMA_OR_END,
    P_DONE,
    P_STR_CONTENT,
};

// JSON number scanner states.
enum num_state : uint8_t { NS_SIGN, NS_ZERO, NS_INT, NS_DOT, NS_FRAC, NS_E, NS_ESIGN, NS_EXP };

struct frame {
    const schema_node * node = nullptr;
    uint8_t kind = K_ROOT;
    uint8_t ph = P_VALUE;

    // object
    std::vector<uint8_t> seen;      // one entry per property
    std::vector<uint8_t> key_alive; // property candidates while additionalProperties=false
    std::vector<std::string> keys;  // property names already emitted (JSON objects are unique-keyed)
    std::string keybuf;
    int child = -1;
    int count = 0;

    // literal / enum
    const std::vector<std::string> * forms = nullptr;
    std::vector<uint8_t> alive;
    int pos = 0;

    // string
    std::string sbuf; // decoded content, only kept for pattern checks
    uint8_t track = 0;
    int slen = 0;
    int esc = 0;
    int hex = 0;
    uint32_t hexv = 0;

    // number
    int nstate = NS_SIGN;
    std::string numbuf;
};

using branch_t = std::vector<frame>;
using run_state = std::vector<branch_t>;

const std::vector<std::string> kBoolForms = {"true", "false"};
const std::vector<std::string> kNullForms = {"null"};

bool is_ws(uint8_t c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}
bool is_digit(uint8_t c) {
    return c >= '0' && c <= '9';
}
bool is_hex(uint8_t c) {
    return is_digit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

const schema_node * follow_ref(const schema_node * n) {
    for (int i = 0; i < 64 && n && n->ref; i++) {
        if (n->ref == n) {
            return n;
        }
        n = n->ref;
    }
    return n;
}

const schema_node * any_schema() {
    static const schema_node * n = [] {
        auto * p = new schema_node();
        p->types = kAllTypes;
        return p;
    }();
    return n;
}

const schema_node * value_node(const branch_t & bi) {
    const frame & f = bi.back();
    switch (f.kind) {
    case K_ROOT:
        return f.node ? follow_ref(f.node) : any_schema();
    case K_ARR: {
        const schema_node * n = follow_ref(f.node);
        return n && n->items ? follow_ref(n->items.get()) : any_schema();
    }
    case K_OBJ: {
        const schema_node * n = follow_ref(f.node);
        if (!n) {
            return any_schema();
        }
        if (f.child >= 0 && (size_t)f.child < n->props.size()) {
            return follow_ref(n->props[(size_t)f.child].schema.get());
        }
        if (n->additional == 2 && n->additional_schema) {
            return follow_ref(n->additional_schema.get());
        }
        return any_schema();
    }
    default:
        return any_schema();
    }
}

bool frame_eq(const frame & a, const frame & b) {
    return a.node == b.node && a.kind == b.kind && a.ph == b.ph && a.seen == b.seen &&
           a.key_alive == b.key_alive && a.keys == b.keys && a.keybuf == b.keybuf && a.child == b.child && a.count == b.count &&
           a.forms == b.forms && a.alive == b.alive && a.pos == b.pos && a.slen == b.slen && a.esc == b.esc &&
           a.hex == b.hex && a.hexv == b.hexv && a.nstate == b.nstate && a.numbuf == b.numbuf &&
           a.sbuf == b.sbuf && a.track == b.track;
}

bool branch_eq(const branch_t & a, const branch_t & b) {
    if (a.size() != b.size()) {
        return false;
    }
    for (size_t i = 0; i < a.size(); i++) {
        if (!frame_eq(a[i], b[i])) {
            return false;
        }
    }
    return true;
}

void dedup(run_state & rs) {
    run_state out;
    out.reserve(rs.size());
    for (auto & b : rs) {
        bool dup = false;
        for (const auto & o : out) {
            if (branch_eq(b, o)) {
                dup = true;
                break;
            }
        }
        if (!dup) {
            out.push_back(std::move(b));
        }
    }
    rs.swap(out);
}

// A value frame completed: pop it and tell its parent that one value is done.
void complete_value(branch_t & bi) {
    if (bi.size() < 2) {
        return;
    }
    bi.pop_back();
    frame & p = bi.back();
    if (p.kind == K_ROOT) {
        p.ph = P_DONE;
    } else if (p.kind == K_OBJ) {
        if (p.child >= 0 && (size_t)p.child < p.seen.size()) {
            p.seen[(size_t)p.child] = 1;
        }
        p.count++;
        p.child = -1;
        p.ph = P_COMMA_OR_END;
    } else if (p.kind == K_ARR) {
        p.count++;
        p.ph = P_COMMA_OR_END;
    }
}

// Numeric prefix pruning.  With an exponential spelling a bounded number can
// jump arbitrarily (6e-1 is 0.6), so bounded numbers are restricted to the
// canonical decimal form (no exponent); that makes the reachable-value interval
// of a prefix computable and lets `score` with maximum 1 reject a leading `9`
// instead of accepting it and dead-ending at the delimiter.  Integers have
// already dropped '.' too, so their reachable set is exact.
bool integral_only_node(const schema_node * n) {
    return n != nullptr && (n->types & T_INT) && !(n->types & T_NUM);
}

bool bounded_node(const schema_node * n) {
    return n != nullptr && (n->has_min || n->has_max || n->has_multiple);
}

bool interval_hits(long double lo, long double hi, long double lb, long double ub) {
    return hi >= lb && lo <= ub;
}

bool num_prefix_ok_buf(const schema_node * n, const std::string & numbuf, int nstate) {
    if (!bounded_node(n)) {
        return true;
    }
    if (numbuf.empty() || numbuf == "-") {
        return true;
    }
    if (nstate == NS_E || nstate == NS_ESIGN || nstate == NS_EXP) {
        return true; // unreachable for bounded numbers (exponent is rejected)
    }
    const long double lb = n->has_min ? (long double)n->min_v : -INFINITY;
    const long double ub = n->has_max ? (long double)n->max_v : INFINITY;
    const bool neg = numbuf[0] == '-';
    std::string mag = neg ? numbuf.substr(1) : numbuf;

    if (nstate == NS_ZERO) {
        // 0 or 0.xxx (and -0/-0.xxx): (-1,1)
        return interval_hits(-1, 1, lb, ub);
    }
    if (nstate == NS_INT) {
        long double p = strtold(mag.c_str(), nullptr);
        long double pow10 = 1;
        for (int k = 0; k < 19; k++) {
            long double lo, hi;
            if (!neg) {
                lo = p * pow10;
                hi = lo + pow10; // stop here, optionally with a fraction
            } else {
                hi = -p * pow10;
                lo = hi - pow10;
            }
            if (interval_hits(lo, hi, lb, ub)) {
                return true;
            }
            if (!neg && lo > ub) {
                return false;
            }
            if (neg && hi < lb) {
                return false;
            }
            pow10 *= 10;
            if (!std::isfinite((double)pow10)) {
                break;
            }
        }
        return false;
    }
    if (nstate == NS_DOT) {
        // integer part is fixed; only a fraction can follow
        long double p = strtold(mag.c_str(), nullptr);
        if (!neg) {
            return interval_hits(p, p + 1, lb, ub);
        }
        return interval_hits(-p - 1, -p, lb, ub);
    }
    if (nstate == NS_FRAC) {
        const long double v = strtold(numbuf.c_str(), nullptr);
        const size_t dot = numbuf.find('.');
        const size_t digits = dot == std::string::npos ? 0 : numbuf.size() - dot - 1;
        long double step = 1;
        for (size_t i = 0; i < digits && i < 30; i++) {
            step /= 10;
        }
        if (v >= 0) {
            return interval_hits(v, v + step, lb, ub);
        }
        return interval_hits(v - step, v, lb, ub);
    }
    return true;
}

bool num_prefix_ok(const frame & f) {
    return num_prefix_ok_buf(follow_ref(f.node ? f.node : any_schema()), f.numbuf, f.nstate);
}

// Number-token fast path: exact state-machine walk with the bounded-range
// check, without constructing branches.
int num_next_state(int st, uint8_t b, bool int_only, bool allow_exp) {
    switch (st) {
    case NS_SIGN:
        if (b == '0') return NS_ZERO;
        if (b >= '1' && b <= '9') return NS_INT;
        return -1;
    case NS_ZERO:
        if (b == '.' && !int_only) return NS_DOT;
        if ((b == 'e' || b == 'E') && !int_only && allow_exp) return NS_E;
        return -1;
    case NS_INT:
        if (is_digit(b)) return NS_INT;
        if (b == '.' && !int_only) return NS_DOT;
        if ((b == 'e' || b == 'E') && !int_only && allow_exp) return NS_E;
        return -1;
    case NS_DOT:
        if (is_digit(b)) return NS_FRAC;
        return -1;
    case NS_FRAC:
        if (is_digit(b)) return NS_FRAC;
        if ((b == 'e' || b == 'E') && allow_exp) return NS_E;
        return -1;
    case NS_E:
        if (b == '+' || b == '-') return NS_ESIGN;
        if (is_digit(b)) return NS_EXP;
        return -1;
    case NS_ESIGN:
        if (is_digit(b)) return NS_EXP;
        return -1;
    case NS_EXP:
        if (is_digit(b)) return NS_EXP;
        return -1;
    default:
        return -1;
    }
}

int num_start_state(uint8_t b) {
    if (b == '-') return NS_SIGN;
    if (b == '0') return NS_ZERO;
    if (b >= '1' && b <= '9') return NS_INT;
    return -1;
}

bool finish_number(const frame & f);

// Value-start literal (true/false/null) token: valid while it is a prefix of
// one of the allowed spellings, or a complete spelling followed by a byte the
// parent admits after a value.
bool literal_piece_ok(const std::string & piece, bool allow_bool, bool allow_null, const frame & parent,
                      size_t lead, bool * decided) {
    static const char * kForms[] = {"true", "false", "null"};
    *decided = false;
    if (lead >= piece.size()) {
        return false;
    }
    const char c = piece[lead];
    if (c == 't' || c == 'f') {
        if (!allow_bool) {
            *decided = true;
            return false;
        }
    } else if (c == 'n') {
        if (!allow_null) {
            *decided = true;
            return false;
        }
    } else {
        return false;
    }
    for (const char * f : kForms) {
        const std::string form(f);
        if (form[0] != c) {
            continue;
        }
        if ((c == 'n') != (form == "null") && (c == 'n' || form == "null")) {
            continue; // bool forms only for t/f, null only for n
        }
        size_t i = 0;
        while (lead + i < piece.size() && i < form.size() && piece[lead + i] == form[i]) {
            i++;
        }
        if (lead + i == piece.size()) {
            *decided = true;
            return true; // an incomplete (or exactly complete) literal prefix
        }
        if (i < form.size()) {
            continue; // diverged inside the spelling
        }
        // The whole form matched; the remaining bytes must be legal after the
        // value.  A single structural byte is decided; longer suffixes defer.
        const uint8_t sb = (uint8_t)piece[lead + i];
        const bool after = is_ws(sb) || sb == ',' || (parent.kind == K_OBJ && sb == '}') ||
                           (parent.kind == K_ARR && sb == ']');
        if (!after) {
            *decided = true;
            return false;
        }
        if (lead + i + 1 == piece.size()) {
            *decided = true;
            return true;
        }
        *decided = false;
        return false;
    }
    *decided = true;
    return false;
}

// A value/continuation token may be a complete number followed by a structural
// byte (",", "}", "]") in the same piece.  Accept it without building a branch
// when the number validates and the suffix is a byte the parent admits after a
// value; anything longer falls through to the exact path.
bool number_split_piece_ok(const schema_node * n, const std::string & piece, const frame & parent,
                           const std::string & prefix, int state, bool at_start, size_t lead, bool * decided) {
    const bool int_only = integral_only_node(n);
    const bool allow_exp = !bounded_node(n);
    std::string buf = prefix;
    int st = state;
    size_t i = 0;
    *decided = false;
    if (at_start) {
        if (lead >= piece.size()) {
            *decided = true;
            return false;
        }
        st = num_start_state((uint8_t)piece[lead]);
        if (st < 0) {
            *decided = true;
            return false;
        }
        buf.push_back(piece[lead]);
        i = lead + 1;
        if (bounded_node(n) && !num_prefix_ok_buf(n, buf, st)) {
            *decided = true;
            return false;
        }
    }
    for (; i < piece.size(); i++) {
        const int ns = num_next_state(st, (uint8_t)piece[i], int_only, allow_exp);
        if (ns < 0) {
            break;
        }
        st = ns;
        buf.push_back(piece[i]);
        if (buf.size() > 48) {
            *decided = true;
            return false;
        }
        if (bounded_node(n) && !num_prefix_ok_buf(n, buf, st)) {
            *decided = true;
            return false;
        }
    }
    *decided = true;
    if (i == piece.size()) {
        return true; // token ends inside the number: a valid prefix
    }
    // The number must be complete before the suffix, and the suffix's first
    // byte must be a byte the parent admits after a value.
    frame nf;
    nf.node = n;
    nf.numbuf = buf;
    nf.nstate = st;
    if (!finish_number(nf)) {
        return false;
    }
    const uint8_t sb = (uint8_t)piece[i];
    const bool after = is_ws(sb) || sb == ',' || (parent.kind == K_OBJ && sb == '}') ||
                       (parent.kind == K_ARR && sb == ']');
    if (!after) {
        return false;
    }
    if (i + 1 == piece.size()) {
        return true;
    }
    *decided = false; // a longer suffix needs the exact path
    return false;
}

bool finish_number(const frame & f) {
    const schema_node * n = follow_ref(f.node ? f.node : any_schema());
    const int st = f.nstate;
    if (!(st == NS_ZERO || st == NS_INT || st == NS_FRAC || st == NS_EXP)) {
        return false;
    }
    char * end = nullptr;
    const double v = strtod(f.numbuf.c_str(), &end);
    if (end == f.numbuf.c_str() || !std::isfinite(v)) {
        return false;
    }
    if (!n) {
        return true;
    }
    const bool integral_only = (n->types & T_INT) && !(n->types & T_NUM);
    if (integral_only) {
        if (v != std::floor(v)) {
            return false;
        }
    }
    if (n->has_min) {
        if (n->min_excl ? !(v > n->min_v) : !(v >= n->min_v)) {
            return false;
        }
    }
    if (n->has_max) {
        if (n->max_excl ? !(v < n->max_v) : !(v <= n->max_v)) {
            return false;
        }
    }
    if (n->has_multiple) {
        const double q = v / n->multiple;
        if (std::fabs(q - std::round(q)) > 1e-9 * std::max(1.0, std::fabs(q))) {
            return false;
        }
    }
    return true;
}

// decoded length of a UTF-8 sequence byte (continuation bytes do not count)
bool is_utf8_cont(uint8_t c) {
    return (c & 0xC0) == 0x80;
}

bool key_append(frame & f, uint8_t c) {
    f.keybuf.push_back((char)c);
    if (f.node == nullptr) {
        return true;
    }
    const schema_node * n = follow_ref(f.node);
    if (!n || n->additional != 0) {
        return true;
    }
    bool any = false;
    for (size_t i = 0; i < f.key_alive.size() && i < n->props.size(); i++) {
        if (!f.key_alive[i]) {
            continue;
        }
        const std::string & name = n->props[i].name;
        if (f.keybuf.size() <= name.size() && (uint8_t)name[f.keybuf.size() - 1] == c) {
            any = true;
        } else {
            f.key_alive[i] = 0;
        }
    }
    return any;
}

void append_utf8(std::string & out, uint32_t cp) {
    if (cp <= 0x7F) {
        out.push_back((char)cp);
    } else if (cp <= 0x7FF) {
        out.push_back((char)(0xC0 | (cp >> 6)));
        out.push_back((char)(0x80 | (cp & 0x3F)));
    } else if (cp <= 0xFFFF) {
        out.push_back((char)(0xE0 | (cp >> 12)));
        out.push_back((char)(0x80 | ((cp >> 6) & 0x3F)));
        out.push_back((char)(0x80 | (cp & 0x3F)));
    } else {
        out.push_back((char)(0xF0 | (cp >> 18)));
        out.push_back((char)(0x80 | ((cp >> 12) & 0x3F)));
        out.push_back((char)(0x80 | ((cp >> 6) & 0x3F)));
        out.push_back((char)(0x80 | (cp & 0x3F)));
    }
}

// Complete a key: resolve it to a declared property (or the additional bucket).
bool finish_key(frame & f) {
    f.ph = P_COLON;
    f.child = -1;
    if (f.node == nullptr) {
        return true;
    }
    const schema_node * n = follow_ref(f.node);
    if (!n) {
        return true;
    }
    if (n->max_props >= 0 && f.count >= n->max_props) {
        return false;
    }
    for (const std::string & k : f.keys) {
        if (k == f.keybuf) {
            return false; // duplicate key
        }
    }
    f.keys.push_back(f.keybuf);
    for (size_t i = 0; i < n->props.size(); i++) {
        if (n->props[i].name == f.keybuf) {
            f.child = (int)i;
            return true;
        }
    }
    return n->additional != 0;
}

bool key_escape_byte(frame & f, uint8_t c) {
    switch (c) {
    case '"':
    case '\\':
    case '/':
        return key_append(f, c);
    case 'b':
        return key_append(f, '\b');
    case 'f':
        return key_append(f, '\f');
    case 'n':
        return key_append(f, '\n');
    case 'r':
        return key_append(f, '\r');
    case 't':
        return key_append(f, '\t');
    default:
        return false;
    }
}

bool integral_only_node(const schema_node * n);
bool num_prefix_ok(const frame & f);

// Start a value: the byte is the first byte of that value.  A schema with
// alternatives produces one branch per matching variant.
void start_value(const branch_t & bi, uint8_t b, run_state & out) {
    const schema_node * n = value_node(bi);
    std::vector<const schema_node *> vars;
    schema_builder::variants(n, vars);
    for (const schema_node * v : vars) {
        if (!v || v->never) {
            continue;
        }
        if (!v->enum_forms.empty()) {
            branch_t nb = bi;
            frame f;
            f.node = v;
            f.kind = K_LIT;
            f.forms = &v->enum_forms;
            f.alive.assign(v->enum_forms.size(), 1);
            f.pos = 0;
            nb.push_back(std::move(f));
            // feed the byte through the literal matcher
            frame & g = nb.back();
            bool any = false;
            bool exact = false;
            for (size_t i = 0; i < g.forms->size(); i++) {
                if (!g.alive[i]) {
                    continue;
                }
                const std::string & s = (*g.forms)[i];
                if (g.pos < (int)s.size() && (uint8_t)s[(size_t)g.pos] == b) {
                    any = true;
                    if (g.pos + 1 == (int)s.size()) {
                        exact = true;
                    }
                } else {
                    g.alive[i] = 0;
                }
            }
            if (!any) {
                continue;
            }
            g.pos++;
            if (exact) {
                complete_value(nb);
            }
            out.push_back(std::move(nb));
            continue;
        }
        uint32_t t = v->types ? v->types : kAllTypes;
        for (uint32_t bit : {(uint32_t)T_OBJ, (uint32_t)T_ARR, (uint32_t)T_STR, (uint32_t)(T_NUM | T_INT),
                             (uint32_t)T_BOOL, (uint32_t)T_NULL}) {
            if (!(t & bit)) {
                continue;
            }
            if (bit == T_OBJ) {
                if (b != '{') {
                    continue;
                }
                branch_t nb = bi;
                frame f;
                f.node = v;
                f.kind = K_OBJ;
                f.ph = P_KEY_OR_END;
                f.seen.assign(v->props.size(), 0);
                if (v->additional == 0) {
                    f.key_alive.assign(v->props.size(), 1);
                }
                nb.push_back(std::move(f));
                out.push_back(std::move(nb));
            } else if (bit == T_ARR) {
                if (b != '[') {
                    continue;
                }
                branch_t nb = bi;
                frame f;
                f.node = v;
                f.kind = K_ARR;
                f.ph = P_VALUE_OR_END;
                nb.push_back(std::move(f));
                out.push_back(std::move(nb));
            } else if (bit == T_STR) {
                if (b != '"') {
                    continue;
                }
                branch_t nb = bi;
                frame f;
                f.node = v;
                f.kind = K_STR;
                f.ph = P_STR_CONTENT;
                f.track = v->has_pattern ? 1 : 0;
                nb.push_back(std::move(f));
                out.push_back(std::move(nb));
            } else if (bit == (T_NUM | T_INT)) {
                if (b != '-' && !is_digit(b)) {
                    continue;
                }
                branch_t nb = bi;
                frame f;
                f.node = v;
                f.kind = K_NUM;
                f.nstate = b == '-' ? NS_SIGN : (b == '0' ? NS_ZERO : NS_INT);
                f.numbuf.assign(1, (char)b);
                if (bounded_node(v) && !num_prefix_ok(f)) {
                    continue;
                }
                nb.push_back(std::move(f));
                out.push_back(std::move(nb));
            } else if (bit == T_BOOL) {
                if (b != 't' && b != 'f') {
                    continue;
                }
                branch_t nb = bi;
                frame f;
                f.node = v;
                f.kind = K_LIT;
                f.forms = &kBoolForms;
                f.alive.assign(kBoolForms.size(), 1);
                for (size_t i = 0; i < kBoolForms.size(); i++) {
                    if (!kBoolForms[i].empty() && (uint8_t)kBoolForms[i][0] == b) {
                        f.pos = 1;
                    } else {
                        f.alive[i] = 0;
                    }
                }
                bool exact = false;
                for (size_t i = 0; i < f.forms->size(); i++) {
                    if (f.alive[i] && (size_t)f.pos == (*f.forms)[i].size()) {
                        exact = true;
                    }
                }
                nb.push_back(std::move(f));
                if (exact) {
                    complete_value(nb);
                }
                out.push_back(std::move(nb));
            } else if (bit == T_NULL) {
                if (b != 'n') {
                    continue;
                }
                branch_t nb = bi;
                frame f;
                f.node = v;
                f.kind = K_LIT;
                f.forms = &kNullForms;
                f.alive.assign(1, 1);
                f.pos = 1;
                nb.push_back(std::move(f));
                out.push_back(std::move(nb));
            }
        }
    }
}

bool required_met(const frame & f) {
    const schema_node * n = follow_ref(f.node);
    if (!n) {
        return true;
    }
    for (size_t i = 0; i < n->required.size() && i < f.seen.size(); i++) {
        if (n->required[i] && !f.seen[i]) {
            return false;
        }
    }
    if (n->min_props >= 0 && f.count < n->min_props) {
        return false;
    }
    return true;
}

// Can this object accept another property?  With additionalProperties=false
// and every declared property already emitted, a comma is a dead end: no key
// could legally follow it.  The model must close the object instead.
bool object_can_take_key(const frame & f) {
    const schema_node * n = follow_ref(f.node);
    if (!n) {
        return true;
    }
    if (n->max_props >= 0 && f.count >= n->max_props) {
        return false;
    }
    if (n->additional != 0) {
        return true;
    }
    for (size_t i = 0; i < f.seen.size() && i < n->props.size(); i++) {
        if (!f.seen[i]) {
            return true;
        }
    }
    return false;
}

bool array_end_ok(const frame & f) {
    const schema_node * n = follow_ref(f.node);
    if (!n) {
        return true;
    }
    return n->min_items < 0 || f.count >= n->min_items;
}

bool array_room(const frame & f) {
    const schema_node * n = follow_ref(f.node);
    if (!n) {
        return true;
    }
    return n->max_items < 0 || f.count < n->max_items;
}

// Feed one byte to one branch.  A byte either consumes (one output branch or
// none) or starts a value (possibly several branches), or completes a number
// and is then reprocessed by the parent.
void feed_byte(branch_t bi, uint8_t b, run_state & out) {
    for (;;) {
        if (bi.empty()) {
            return;
        }
        frame & f = bi.back();
        if (f.kind == K_ROOT) {
            if (f.ph == P_DONE) {
                // The document is complete: only EOS is allowed.  Permitting
                // trailing whitespace here lets a model spend its whole token
                // budget on spaces after a finished object; forcing EOS ends
                // the request at the value instead.
                return;
            }
            // No leading whitespace: the constrained document must start with
            // the value itself, so the model cannot spend its budget on spaces
            // before it (whitespace inside the document remains legal).
            if (is_ws(b)) {
                return;
            }
            start_value(bi, b, out);
            return;
        }
        if (f.kind == K_OBJ) {
            switch (f.ph) {
            case P_KEY_OR_END:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == '}') {
                    if (!required_met(f)) {
                        return;
                    }
                    complete_value(bi);
                    out.push_back(std::move(bi)); // '}' is consumed with the frame
                    return;
                }
                if (b == '"') {
                    if (!object_can_take_key(f)) {
                        return;
                    }
                    f.ph = P_KEY;
                    f.keybuf.clear();
                    f.esc = 0;
                    if (f.node && follow_ref(f.node)->additional == 0) {
                        f.key_alive.assign(follow_ref(f.node)->props.size(), 1);
                    }
                    out.push_back(std::move(bi));
                    return;
                }
                return;
            case P_KEY_AFTER_COMMA:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == '"') {
                    f.ph = P_KEY;
                    f.keybuf.clear();
                    f.esc = 0;
                    if (f.node && follow_ref(f.node)->additional == 0) {
                        f.key_alive.assign(follow_ref(f.node)->props.size(), 1);
                    }
                    out.push_back(std::move(bi));
                    return;
                }
                return;
            case P_KEY:
                if (f.esc == 2) {
                    if (!is_hex(b)) {
                        return;
                    }
                    const int v = is_digit(b) ? b - '0' : ((b | 0x20) - 'a' + 10);
                    f.hexv = (f.hexv << 4) | (uint32_t)v;
                    if (--f.hex == 0) {
                        std::string u;
                        append_utf8(u, f.hexv);
                        for (unsigned char uc : u) {
                            if (!key_append(f, uc)) {
                                return;
                            }
                        }
                        f.esc = 0;
                    }
                    out.push_back(std::move(bi));
                    return;
                }
                if (f.esc == 1) {
                    f.esc = 0;
                    if (b == 'u') {
                        f.esc = 2;
                        f.hex = 4;
                        f.hexv = 0;
                    } else if (!key_escape_byte(f, b)) {
                        return;
                    }
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == '"') {
                    if (!finish_key(f)) {
                        return;
                    }
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == '\\') {
                    f.esc = 1;
                    out.push_back(std::move(bi));
                    return;
                }
                if (b < 0x20) {
                    return;
                }
                if (!key_append(f, b)) {
                    return;
                }
                out.push_back(std::move(bi));
                return;
            case P_COLON:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == ':') {
                    f.ph = P_VALUE;
                    out.push_back(std::move(bi));
                    return;
                }
                return;
            case P_VALUE:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                start_value(bi, b, out);
                return;
            case P_COMMA_OR_END:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == ',') {
                    if (!object_can_take_key(f)) {
                        return;
                    }
                    f.ph = P_KEY_AFTER_COMMA;
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == '}') {
                    if (!required_met(f)) {
                        return;
                    }
                    complete_value(bi);
                    out.push_back(std::move(bi)); // consumed
                    return;
                }
                return;
            default:
                return;
            }
        }
        if (f.kind == K_ARR) {
            switch (f.ph) {
            case P_VALUE_OR_END:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == ']') {
                    if (!array_end_ok(f)) {
                        return;
                    }
                    complete_value(bi);
                    out.push_back(std::move(bi)); // consumed
                    return;
                }
                if (!array_room(f)) {
                    return;
                }
                start_value(bi, b, out);
                return;
            case P_VALUE_AFTER_COMMA:
            case P_VALUE:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (!array_room(f)) {
                    return;
                }
                start_value(bi, b, out);
                return;
            case P_COMMA_OR_END:
                if (is_ws(b)) {
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == ',') {
                    if (!array_room(f)) {
                        return; // maxItems already reached: only ']' may follow
                    }
                    f.ph = P_VALUE_AFTER_COMMA;
                    out.push_back(std::move(bi));
                    return;
                }
                if (b == ']') {
                    if (!array_end_ok(f)) {
                        return;
                    }
                    complete_value(bi);
                    out.push_back(std::move(bi)); // consumed
                    return;
                }
                return;
            default:
                return;
            }
        }
        if (f.kind == K_STR) {
            if (f.esc == 2) {
                if (!is_hex(b)) {
                    return;
                }
                const int v = is_digit(b) ? b - '0' : ((b | 0x20) - 'a' + 10);
                f.hexv = (f.hexv << 4) | (uint32_t)v;
                if (--f.hex == 0) {
                    f.esc = 0;
                    if (f.track) {
                        append_utf8(f.sbuf, f.hexv);
                    }
                    f.slen++;
                    if (f.node) {
                        const schema_node * n = follow_ref(f.node);
                        if (n && n->max_len >= 0 && f.slen > n->max_len) {
                            return;
                        }
                    }
                }
                out.push_back(std::move(bi));
                return;
            }
            if (f.esc == 1) {
                f.esc = 0;
                if (b == 'u') {
                    f.esc = 2;
                    f.hex = 4;
                    f.hexv = 0;
                    out.push_back(std::move(bi));
                    return;
                }
                char decoded = 0;
                switch (b) {
                case '"': decoded = '"'; break;
                case '\\': decoded = '\\'; break;
                case '/': decoded = '/'; break;
                case 'b': decoded = '\b'; break;
                case 'f': decoded = '\f'; break;
                case 'n': decoded = '\n'; break;
                case 'r': decoded = '\r'; break;
                case 't': decoded = '\t'; break;
                default: return;
                }
                f.slen++;
                if (f.track) {
                    f.sbuf.push_back(decoded);
                }
                if (f.node) {
                    const schema_node * n = follow_ref(f.node);
                    if (n && n->max_len >= 0 && f.slen > n->max_len) {
                        return;
                    }
                }
                out.push_back(std::move(bi));
                return;
            }
            if (b == '"') {
                if (f.node) {
                    const schema_node * n = follow_ref(f.node);
                    if (n) {
                        if (n->min_len >= 0 && f.slen < n->min_len) {
                            return;
                        }
                        if (n->has_pattern) {
                            const std::string & content = f.track ? f.sbuf : f.keybuf;
                            try {
                                std::regex re(n->pattern, std::regex::ECMAScript);
                                if (!std::regex_match(content, re)) {
                                    return;
                                }
                            } catch (...) {
                                // an invalid pattern cannot be enforced
                            }
                        }
                    }
                }
                complete_value(bi);
                out.push_back(std::move(bi)); // the quote is consumed
                return;
            }
            if (b == '\\') {
                f.esc = 1;
                out.push_back(std::move(bi));
                return;
            }
            if (b < 0x20) {
                return;
            }
            if (!is_utf8_cont(b)) {
                f.slen++;
            }
            if (f.track) {
                f.sbuf.push_back((char)b);
            }
            if (f.node) {
                const schema_node * n = follow_ref(f.node);
                if (n && n->max_len >= 0 && f.slen > n->max_len) {
                    return;
                }
            }
            out.push_back(std::move(bi));
            return;
        }
        if (f.kind == K_LIT) {
            bool any = false;
            bool exact = false;
            for (size_t i = 0; i < f.forms->size(); i++) {
                if (!f.alive[i]) {
                    continue;
                }
                const std::string & s = (*f.forms)[i];
                if (f.pos < (int)s.size() && (uint8_t)s[(size_t)f.pos] == b) {
                    any = true;
                    if (f.pos + 1 == (int)s.size()) {
                        exact = true;
                    }
                } else {
                    f.alive[i] = 0;
                }
            }
            if (!any) {
                return;
            }
            f.pos++;
            if (exact) {
                complete_value(bi);
            }
            out.push_back(std::move(bi));
            return;
        }
        if (f.kind == K_NUM) {
            const schema_node * numn = follow_ref(f.node ? f.node : any_schema());
            const bool int_only = integral_only_node(numn);
            const int ns = num_next_state(f.nstate, b, int_only, !bounded_node(numn));
            if (ns >= 0) {
                f.nstate = ns;
                f.numbuf.push_back((char)b);
                if (bounded_node(numn) && !num_prefix_ok(f)) {
                    return;
                }
                out.push_back(std::move(bi));
                return;
            }
            // Not part of this number: finish it and let the parent see the byte.
            if (!finish_number(f)) {
                return;
            }
            complete_value(bi);
            continue;
        }
        return;
    }
}

void feed_run(const run_state & rs, uint8_t b, run_state & out) {
    out.clear();
    for (const auto & br : rs) {
        feed_byte(br, b, out);
        if (out.size() > 256) {
            break;
        }
    }
    dedup(out);
}

bool eos_ok_branch(branch_t bi) {
    // A number at the root completes at EOS without a delimiter.
    if (bi.size() == 2 && bi[0].kind == K_ROOT && bi[0].ph == P_VALUE && bi[1].kind == K_NUM) {
        return finish_number(bi[1]);
    }
    return bi.size() == 1 && bi[0].kind == K_ROOT && bi[0].ph == P_DONE;
}

bool eos_ok(const run_state & rs) {
    for (const auto & b : rs) {
        if (eos_ok_branch(b)) {
            return true;
        }
    }
    return false;
}

// ---------------------------------------------------------------------------
// token byte table
// ---------------------------------------------------------------------------

struct piece_table {
    std::vector<std::string> pieces;
    std::vector<uint8_t> is_eos;
    // Plain JSON-string content (printable, no quote/backslash/control).  The
    // hot path uses this to accept a token inside a string/key without running
    // the automaton, which is the difference between ~1 ms and ~70 ms per step
    // on a 248k vocabulary.
    std::vector<uint8_t> str_safe;
    std::vector<uint8_t> ws_only;
    std::vector<uint8_t> num_only;
    std::vector<uint16_t> lead_ws;
    std::vector<uint16_t> ulen;
    std::array<std::vector<int>, 256> buckets;
    std::array<std::vector<int>, 256> nz_buckets; // by first non-whitespace byte
    std::vector<int> single_byte_tokens;
    std::vector<int> all_ws_tokens;
    std::vector<int> str_safe_tokens;
    int n_eos = 0;
};

std::shared_ptr<const piece_table> build_piece_table(const std::vector<std::string> & pieces,
                                                     const std::vector<int> & eos_ids) {
    auto t = std::make_shared<piece_table>();
    t->pieces = pieces;
    t->is_eos.assign(pieces.size(), 0);
    t->str_safe.assign(pieces.size(), 0);
    t->ws_only.assign(pieces.size(), 0);
    t->num_only.assign(pieces.size(), 0);
    t->lead_ws.assign(pieces.size(), 0);
    t->ulen.assign(pieces.size(), 0);
    for (int id : eos_ids) {
        if (id >= 0 && id < (int)t->is_eos.size()) {
            t->is_eos[(size_t)id] = 1;
            t->n_eos++;
        }
    }
    for (size_t i = 0; i < pieces.size(); i++) {
        uint16_t units = 0;
        bool safe = !pieces[i].empty();
        for (unsigned char c : pieces[i]) {
            if (c < 0x20 || c == '"' || c == '\\') {
                safe = false;
            }
            if ((c & 0xC0) != 0x80 && units < 0xFFFF) {
                units++;
            }
        }
        t->str_safe[i] = safe ? 1 : 0;
        t->ulen[i] = units;
        uint16_t lead = 0;
        bool all_ws = !pieces[i].empty();
        for (unsigned char c : pieces[i]) {
            if (!is_ws(c)) {
                all_ws = false;
                break;
            }
            lead++;
        }
        t->ws_only[i] = all_ws ? 1 : 0;
        bool numok = !pieces[i].empty();
        for (unsigned char c : pieces[i]) {
            if (!(is_digit(c) || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E')) {
                numok = false;
                break;
            }
        }
        t->num_only[i] = numok ? 1 : 0;
        if (lead == 0) {
            // still record the leading whitespace run for the mixed case
            while (lead < pieces[i].size() && is_ws((unsigned char)pieces[i][lead])) {
                lead++;
            }
        }
        t->lead_ws[i] = lead;
        if (pieces[i].empty() || t->is_eos[i]) {
            continue;
        }
        t->buckets[(uint8_t)pieces[i][0]].push_back((int)i);
        if (all_ws) {
            t->all_ws_tokens.push_back((int)i);
        }
        if (!pieces[i].empty() && (size_t)lead + 1 == pieces[i].size()) {
            t->single_byte_tokens.push_back((int)i);
        }
        if (t->str_safe[i]) {
            t->str_safe_tokens.push_back((int)i);
        }
        if (lead < pieces[i].size()) {
            t->nz_buckets[(uint8_t)pieces[i][lead]].push_back((int)i);
        }
    }
    return t;
}

} // namespace

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

struct guided_constraint {
    std::shared_ptr<const piece_table> vocab;
    std::shared_ptr<const schema_node> root;
    // Every compiled node (including $defs targets referenced through raw
    // pointers) lives here for the constraint's lifetime.
    std::vector<std::shared_ptr<const schema_node>> arena;
};

class guided_state {
public:
    run_state runs;
    bool disabled = false;
};

std::shared_ptr<const guided_constraint> make_guided_constraint(const std::string & schema_json,
                                                                std::vector<std::string> pieces,
                                                                std::vector<int> eos_ids) {
    json doc;
    if (schema_json.empty()) {
        doc = json::parse("{\"type\":\"object\"}");
    } else {
        try {
            doc = json::parse(schema_json);
        } catch (const std::exception & ex) {
            throw std::runtime_error(std::string("invalid JSON schema: ") + ex.what());
        }
    }
    schema_builder b;
    b.root = &doc;
    if (doc.is_object()) {
        for (const char * key : {"$defs", "definitions"}) {
            if (doc.contains(key) && doc[key].is_object()) {
                for (auto it = doc[key].begin(); it != doc[key].end(); ++it) {
                    if (it.value().is_object() || it.value().is_boolean()) {
                        b.defs[it.key()] = &it.value();
                    }
                }
            }
        }
    }
    auto root = b.compile(doc, 0);
    if (root && root->never) {
        throw std::runtime_error("JSON schema admits no value");
    }
    auto gc = std::make_shared<guided_constraint>();
    gc->vocab = build_piece_table(pieces, eos_ids);
    gc->root = root;
    for (auto & kv : b.memo) {
        gc->arena.push_back(kv.second);
    }
    return gc;
}

std::shared_ptr<const guided_constraint> make_guided_json_object(const tokenizer & tk) {
    return make_guided_from_tokenizer(tk, "{\"type\":\"object\"}");
}

static bool guided_debug() {
    static const bool d = std::getenv("PF_GUIDED_DEBUG") != nullptr;
    return d;
}

std::shared_ptr<const guided_constraint> make_guided_from_tokenizer(const tokenizer & tk,
                                                                    const std::string & schema_json) {
    // The tokenizer is immutable once loaded, so its byte table is cached.  The
    // map is keyed by address: the tokenizer outlives every engine that uses it.
    struct cache_entry {
        std::shared_ptr<const piece_table> table;
        std::vector<std::string> pieces;
        std::vector<int> eos;
    };
    static std::mutex mu;
    static std::unordered_map<const tokenizer *, cache_entry> cache;
    std::shared_ptr<const piece_table> table;
    {
        std::lock_guard<std::mutex> lk(mu);
        auto it = cache.find(&tk);
        if (it == cache.end()) {
            cache_entry e;
            e.pieces.reserve((size_t)std::max(0, tk.n_vocab));
            for (int i = 0; i < tk.n_vocab; i++) {
                e.pieces.push_back(tk.token_piece(i));
            }
            for (int id : {tk.eos_id, tk.eot_id, tk.im_end_id}) {
                if (id >= 0 && id < tk.n_vocab &&
                    std::find(e.eos.begin(), e.eos.end(), id) == e.eos.end()) {
                    e.eos.push_back(id);
                }
            }
            e.table = build_piece_table(e.pieces, e.eos);
            it = cache.emplace(&tk, std::move(e)).first;
        }
        table = it->second.table;
    }

    json doc;
    if (schema_json.empty()) {
        doc = json::parse("{\"type\":\"object\"}");
    } else {
        try {
            doc = json::parse(schema_json);
        } catch (const std::exception & ex) {
            throw std::runtime_error(std::string("invalid JSON schema: ") + ex.what());
        }
    }
    schema_builder b;
    b.root = &doc;
    if (doc.is_object()) {
        for (const char * key : {"$defs", "definitions"}) {
            if (doc.contains(key) && doc[key].is_object()) {
                for (auto it = doc[key].begin(); it != doc[key].end(); ++it) {
                    if (it.value().is_object() || it.value().is_boolean()) {
                        b.defs[it.key()] = &it.value();
                    }
                }
            }
        }
    }
    auto root = b.compile(doc, 0);
    if (root && root->never) {
        throw std::runtime_error("JSON schema admits no value");
    }
    auto gc = std::make_shared<guided_constraint>();
    gc->vocab = table;
    gc->root = root;
    for (auto & kv : b.memo) {
        gc->arena.push_back(kv.second);
    }
    if (guided_debug()) {
        fprintf(stderr, "[guided] vocab=%d eos=", (int)table->pieces.size());
        for (size_t i = 0; i < table->is_eos.size(); i++) {
            if (table->is_eos[i]) {
                fprintf(stderr, "%d ", (int)i);
            }
        }
        fprintf(stderr, "(eos_id=%d eot_id=%d im_end_id=%d)\n", tk.eos_id, tk.eot_id, tk.im_end_id);
    }
    return gc;
}

std::shared_ptr<guided_state> make_guided_state(const guided_constraint & gc) {
    auto st = std::make_shared<guided_state>();
    branch_t root;
    frame f;
    f.node = gc.root.get();
    f.kind = K_ROOT;
    f.ph = P_VALUE;
    root.push_back(std::move(f));
    st->runs.push_back(std::move(root));
    return st;
}

bool value_start_state(const frame & f) {
    if (f.ph != P_VALUE && f.ph != P_VALUE_OR_END && f.ph != P_VALUE_AFTER_COMMA) {
        return false;
    }
    return f.kind == K_ROOT || f.kind == K_OBJ || f.kind == K_ARR;
}

bool key_start_state(const frame & f) {
    return f.kind == K_OBJ && (f.ph == P_KEY_OR_END || f.ph == P_KEY_AFTER_COMMA);
}

// A token that opens a string (`"`-prefixed) is the common case at a value
// start; accept it without the automaton when its content is plain.  Tokens
// with escapes, a pattern to check, or trailing bytes after the closing quote
// fall through to the exact simulation.
bool string_piece_ok(const schema_node * n, const std::string & piece, int base_len, size_t q = 0) {
    if (q >= piece.size() || piece[q] != '"' || !n || (n->types & T_STR) == 0 || !n->enum_forms.empty() ||
        n->has_pattern) {
        return false;
    }
    int units = 0;
    size_t i = q + 1;
    for (; i < piece.size(); i++) {
        const unsigned char c = (unsigned char)piece[i];
        if (c == '"') {
            break;
        }
        if (c == '\\' || c < 0x20) {
            return false;
        }
        if ((c & 0xC0) != 0x80) {
            units++;
        }
    }
    if (i < piece.size() && i + 1 != piece.size()) {
        return false; // bytes after the closing quote: exact simulation
    }
    const int len = base_len + units;
    if (n->max_len >= 0 && len > n->max_len) {
        return false;
    }
    if (i < piece.size() && n->min_len >= 0 && len < n->min_len) {
        return false;
    }
    return true;
}

bool key_piece_ok(const frame & f, const std::string & piece, const schema_node * n, size_t q = 0) {
    if (q >= piece.size() || piece[q] != '"' || !n) {
        return false;
    }
    size_t i = q + 1;
    std::string content;
    for (; i < piece.size(); i++) {
        const unsigned char c = (unsigned char)piece[i];
        if (c == '"') {
            break;
        }
        if (c == '\\' || c < 0x20) {
            return false;
        }
        content.push_back((char)c);
    }
    const bool closed = i < piece.size();
    if (closed && i + 1 != piece.size()) {
        return false; // bytes after the quote (colon, comma, ...)
    }
    const std::string key = (f.ph == P_KEY ? f.keybuf : std::string()) + content;
    if (!closed) {
        if (n->additional != 0) {
            return true;
        }
        for (const auto & p : n->props) {
            if (key.size() <= p.name.size() && p.name.compare(0, key.size(), key) == 0) {
                return true;
            }
        }
        return false;
    }
    if (n->max_props >= 0 && f.count >= n->max_props) {
        return false;
    }
    for (size_t k = 0; k < n->props.size(); k++) {
        if (n->props[k].name != key) {
            continue;
        }
        return !(k < f.seen.size() && f.seen[k]);
    }
    if (n->additional == 0) {
        return false;
    }
    for (const auto & k : f.keys) {
        if (k == key) {
            return false;
        }
    }
    return true;
}

// Fast path: a plain (no quote/backslash/control) piece extends an object key.
// additionalProperties=false requires it to be a prefix of one of the declared
// property names at the current key offset.
bool key_piece_prefix_ok(const frame & f, const std::string & piece, const schema_node * n) {
    if (!n || n->additional != 0) {
        return true;
    }
    const size_t off = f.keybuf.size();
    for (size_t i = 0; i < n->props.size(); i++) {
        const std::string & name = n->props[i].name;
        if (off + piece.size() <= name.size() && memcmp(name.data() + off, piece.data(), piece.size()) == 0) {
            return true;
        }
    }
    return false;
}

bool guided_apply(const guided_constraint & gc, guided_state & st, float * logits, int n_vocab) {
    if (st.disabled || !gc.vocab || !gc.root) {
        return true;
    }
    const bool gdbg = guided_debug();
    const auto gt0 = gdbg ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
    size_t gsim = 0;
    const piece_table & pt = *gc.vocab;
    const int n = std::min(n_vocab, (int)pt.pieces.size());
    if (n <= 0) {
        return true;
    }
    const bool eos_allowed = eos_ok(st.runs);
    // Which first bytes can extend at least one surviving branch?
    uint8_t first[256] = {0};
    for (int b = 0; b < 256; b++) {
        run_state tmp;
        feed_run(st.runs, (uint8_t)b, tmp);
        first[b] = tmp.empty() ? 0 : 1;
    }
    std::vector<uint8_t> ok((size_t)n, 0);
    std::vector<uint8_t> decided((size_t)n, 0);
    int count = 0;
    if (eos_allowed) {
        for (int i = 0; i < n; i++) {
            if (pt.is_eos[(size_t)i]) {
                ok[(size_t)i] = 1;
                count++;
            }
        }
    }
    // Plain string content and plain key bytes need no automaton run: both are
    // "any printable byte" states, differing only in the key-prefix test.
    bool str_fast = false, key_fast = false, value_str_fast = false, key_start_fast = false;
    bool value_num_fast = false, num_fast = false;
    bool value_bool_fast = false, value_null_fast = false;
    int str_left = -1;
    const schema_node * key_node = nullptr;
    std::vector<const schema_node *> value_str_nodes;
    std::vector<const schema_node *> value_num_nodes;
    if (st.runs.size() == 1 && !st.runs[0].empty()) {
        const frame & top = st.runs[0].back();
        if (top.kind == K_NUM) {
            num_fast = true;
        } else if (top.kind == K_STR && top.ph == P_STR_CONTENT && top.esc == 0 && top.track == 0) {
            str_fast = true;
            const schema_node * n = follow_ref(top.node ? top.node : any_schema());
            if (n && n->max_len >= 0) {
                str_left = n->max_len - top.slen;
            }
        } else if (top.kind == K_OBJ && top.ph == P_KEY && top.esc == 0) {
            key_fast = true;
            key_node = follow_ref(top.node ? top.node : any_schema());
        } else if (value_start_state(top)) {
            value_str_fast = true;
            const schema_node * n = value_node(st.runs[0]);
            std::vector<const schema_node *> vars;
            schema_builder::variants(n, vars);
            for (const schema_node * v : vars) {
                if (v && (v->types & T_STR) && v->enum_forms.empty()) {
                    value_str_nodes.push_back(v);
                }
            }
            value_str_fast = !value_str_nodes.empty();
            for (const schema_node * v : vars) {
                if (v && (v->types & (T_NUM | T_INT)) && v->enum_forms.empty()) {
                    value_num_nodes.push_back(v);
                }
                if (v && (v->types & T_BOOL) && v->enum_forms.empty()) {
                    value_bool_fast = true;
                }
                if (v && (v->types & T_NULL) && v->enum_forms.empty()) {
                    value_null_fast = true;
                }
            }
            value_num_fast = !value_num_nodes.empty();
        } else if (key_start_state(top)) {
            key_start_fast = true;
            key_node = follow_ref(top.node ? top.node : any_schema());
            key_start_fast = object_can_take_key(top);
        }
    }
    if (str_fast) {
        for (int i : pt.str_safe_tokens) {
            if (i >= n) {
                continue;
            }
            if (str_left >= 0 && (int)pt.ulen[(size_t)i] > str_left) {
                continue; // rejected (and skipped again in the slow loop)
            }
            if (!ok[(size_t)i]) {
                ok[(size_t)i] = 1;
                count++;
            }
        }
    } else if (key_fast) {
        for (int i : pt.str_safe_tokens) {
            if (i >= n) {
                continue;
            }
            if (key_piece_prefix_ok(st.runs[0].back(), pt.pieces[(size_t)i], key_node) && !ok[(size_t)i]) {
                ok[(size_t)i] = 1;
                count++;
            }
        }
    }
    {
        // Whitespace-only tokens are structural no-ops: if the state admits a
        // whitespace byte, a token made only of whitespace is legal and leaves
        // the state unchanged.  This is exact, and it avoids simulating the
        // ~100k leading-space vocabulary entries on every step.
        const uint8_t ws_first = (uint8_t)' ';
        const bool ws_ok = first[ws_first] || first[(uint8_t)'\n'] || first[(uint8_t)'\t'] || first[0x0d];
        if (ws_ok) {
            for (int i : pt.all_ws_tokens) {
                if (i < n && !ok[(size_t)i]) {
                    ok[(size_t)i] = 1;
                    count++;
                }
            }
        }
        // Indented string/key tokens ("\n  \"foo\"") are the next most common
        // shape; test the quoted part directly instead of the whole automaton.
        if ((value_str_fast || key_start_fast) && !st.runs.empty() && !st.runs[0].empty()) {
            const frame & top = st.runs[0].back();
            for (int i : pt.nz_buckets[(size_t)'"']) {
                if (i >= n || ok[(size_t)i]) {
                    continue;
                }
                const std::string & p = pt.pieces[(size_t)i];
                const size_t q = pt.lead_ws[(size_t)i];
                if (q >= p.size() || p[q] != '"') {
                    continue;
                }
                if (q > 0 && !first[(uint8_t)p[0]]) {
                    continue; // leading whitespace is not legal in this state
                }
                bool good = false;
                if (value_str_fast) {
                    for (const schema_node * v : value_str_nodes) {
                        if (string_piece_ok(v, p, 0, q)) {
                            good = true;
                            break;
                        }
                    }
                } else {
                    good = key_piece_ok(top, p, key_node, q);
                }
                if (good) {
                    ok[(size_t)i] = 1;
                    count++;
                }
            }
        }
    }
    {
        // A one-byte token that is legal as the next byte is always valid; it
        // covers the bulk of structural tokens (braces, commas, colons, digits)
        // and any indentation in front of them.
        for (int i : pt.single_byte_tokens) {
            if (i >= n || ok[(size_t)i]) {
                continue;
            }
            const std::string & p = pt.pieces[(size_t)i];
            const size_t lead = pt.lead_ws[(size_t)i];
            if (lead > 0 && !first[(uint8_t)p[0]]) {
                continue;
            }
            if (first[(uint8_t)p[lead]]) {
                ok[(size_t)i] = 1;
                count++;
            }
            decided[(size_t)i] = 1;
        }
    }
    if ((value_bool_fast || value_null_fast) && !st.runs[0].empty()) {
        const frame & top = st.runs[0].back();
        for (char c : {'t', 'f', 'n'}) {
            for (int i : pt.nz_buckets[(uint8_t)c]) {
                if (i >= n || ok[(size_t)i]) {
                    continue;
                }
                const std::string & p = pt.pieces[(size_t)i];
                const size_t lead = pt.lead_ws[(size_t)i];
                if (lead > 0 && !first[(uint8_t)p[0]]) {
                    continue;
                }
                bool d = false;
                const bool good = literal_piece_ok(p, value_bool_fast, value_null_fast, top, lead, &d);
                decided[(size_t)i] = decided[(size_t)i] || d;
                if (good) {
                    ok[(size_t)i] = 1;
                    count++;
                }
            }
        }
    }
    if ((value_num_fast || num_fast) && !st.runs[0].empty()) {
        const frame & top = st.runs[0].back();
        std::vector<int> num_first;
        for (int c = '0'; c <= '9'; c++) {
            num_first.push_back(c);
        }
        num_first.push_back('-');
        if (num_fast) {
            for (int c : {'.', '+', 'e', 'E'}) {
                num_first.push_back(c);
            }
        }
        for (int firstc : num_first) {
            for (int i : pt.nz_buckets[(size_t)firstc]) {
            if (i >= n || ok[(size_t)i]) {
                continue;
            }
            const std::string & p = pt.pieces[(size_t)i];
            if (p.empty()) {
                continue;
            }
            const size_t lead = pt.lead_ws[(size_t)i];
            if (lead >= p.size()) {
                continue;
            }
            if (lead > 0 && !first[(uint8_t)p[0]]) {
                continue;
            }
            bool good = false;
            if (num_fast) {
                const frame & parent = st.runs[0].size() >= 2 ? st.runs[0][st.runs[0].size() - 2] : top;
                bool d = false;
                good = number_split_piece_ok(follow_ref(top.node ? top.node : any_schema()), p, parent,
                                             top.numbuf, top.nstate, false, lead, &d);
                decided[(size_t)i] = decided[(size_t)i] || d;
            } else {
                for (const schema_node * v : value_num_nodes) {
                    bool d = false;
                    const bool g = number_split_piece_ok(v, p, top, std::string(), NS_SIGN, true, lead, &d);
                    decided[(size_t)i] = decided[(size_t)i] || d;
                    if (g) {
                        good = true;
                        break;
                    }
                }
            }
            if (good) {
                ok[(size_t)i] = 1;
                count++;
            }
            }
        }
    }
    for (int b = 0; b < 256; b++) {
        if (!first[b]) {
            continue;
        }
        for (int tok : pt.buckets[(size_t)b]) {
            if (tok >= n || ok[(size_t)tok]) {
                continue;
            }
            if (pt.ws_only[(size_t)tok]) {
                continue; // accepted above when whitespace is legal; otherwise first[] was 0
            }
            if (decided[(size_t)tok]) {
                continue; // exact decision by the numeric fast path
            }
            // A leading-whitespace token's first non-whitespace byte must be
            // legal from this same state (whitespace does not change it).  Most
            // BPE "-word" entries fail this immediately, without a simulation.
            {
                const size_t lw = pt.lead_ws[(size_t)tok];
                if (lw > 0 && lw < pt.pieces[(size_t)tok].size() &&
                    !first[(uint8_t)pt.pieces[(size_t)tok][lw]]) {
                    continue;
                }
            }
            if ((str_fast || key_fast) && pt.str_safe[(size_t)tok]) {
                continue; // decided by the fast path (accepted or length/shape rejected)
            }
            const std::string & piece = pt.pieces[(size_t)tok];
            gsim++;
            run_state cur = st.runs;
            bool good = true;
            for (unsigned char c : piece) {
                run_state next;
                feed_run(cur, c, next);
                if (next.empty()) {
                    good = false;
                    break;
                }
                cur.swap(next);
            }
            if (good) {
                ok[(size_t)tok] = 1;
                count++;
            }
        }
    }
    if (count == 0) {
        if (guided_debug()) {
            fprintf(stderr, "[guided] dead end: branches=%zu eos_ok=%d n_eos=%d topkind=%d ph=%d\n",
                    st.runs.size(), (int)eos_allowed, pt.n_eos,
                    st.runs.empty() || st.runs[0].empty() ? -1 : (int)st.runs[0].back().kind,
                    st.runs.empty() || st.runs[0].empty() ? -1 : (int)st.runs[0].back().ph);
        }
        st.disabled = true;
        return false;
    }
    for (int i = 0; i < n; i++) {
        if (!ok[(size_t)i]) {
            logits[i] = -std::numeric_limits<float>::infinity();
        }
    }
    // A vocabulary id the constraint's table does not cover has no piece to
    // validate; never let it through.
    for (int i = n; i < n_vocab; i++) {
        logits[i] = -std::numeric_limits<float>::infinity();
    }
    if (gdbg) {
        const double us = std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - gt0).count();
        fprintf(stderr, "[guided] apply us=%.0f sim=%zu allowed=%d fast=%d%d%d%d branches=%zu\n", us, gsim, count,
                (int)str_fast, (int)key_fast, (int)value_str_fast, (int)key_start_fast, st.runs.size());
    }
    return true;
}

void guided_commit(const guided_constraint & gc, guided_state & st, int token) {
    if (st.disabled || !gc.vocab) {
        return;
    }
    const piece_table & pt = *gc.vocab;
    if (token < 0 || token >= (int)pt.pieces.size() || pt.is_eos[(size_t)token]) {
        return;
    }
    const std::string & piece = pt.pieces[(size_t)token];
    run_state cur;
    cur.swap(st.runs);
    for (unsigned char c : piece) {
        run_state next;
        feed_run(cur, c, next);
        if (next.empty()) {
            st.disabled = true;
            st.runs.clear();
            return;
        }
        cur.swap(next);
    }
    st.runs.swap(cur);
}

bool guided_finished(const guided_constraint & gc, const guided_state & st) {
    if (st.disabled || !gc.vocab) {
        return true;
    }
    return eos_ok(st.runs);
}

} // namespace si
